python - <<'PY'
import os
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

in_path = '/root/data/workbook.xlsx'
os.makedirs('/root/output', exist_ok=True)

wb = load_workbook(in_path, data_only=False)
print('Sheets:', wb.sheetnames)

ws = wb['Task']
print('\n=== Task!A1:L55 values ===')
for r in range(1, 56):
    row_vals = []
    for c in range(1, 13):
        v = ws.cell(row=r, column=c).value
        row_vals.append(v)
    print(f"{r:02d}", row_vals)

# Helper to describe fill

def fill_sig(cell):
    f = cell.fill
    if f is None:
        return None
    if f.patternType is None:
        return None
    fg = f.fgColor
    bg = f.bgColor
    def cdesc(color):
        if color is None:
            return None
        return (color.type, color.rgb, color.indexed, color.theme)
    return (f.patternType, cdesc(fg), cdesc(bg))

# Find yellow-ish filled cells in Task A1:L55
print('\n=== Task!A1:L55 cells with solid fill ===')
solid = []
for r in range(1, 56):
    for c in range(1, 13):
        cell = ws.cell(row=r, column=c)
        sig = fill_sig(cell)
        if sig and sig[0] == 'solid':
            solid.append((cell.coordinate, sig, cell.value))
for coord, sig, val in solid:
    print(coord, sig, 'value=', val)

# Print lookup keys exactly
ranges = [('D12','D17'),('D19','D24'),('D26','D31'),('D35','D40')]
for a,b in ranges:
    print(f"\nTask!{a}:{b} values")
    for row in range(ws[a].row, ws[b].row+1):
        print(f"D{row}", ws[f"D{row}"].value)

print('\nTask!H10:L10 values')
for c in range(8, 13):
    coord = f"{get_column_letter(c)}10"
    print(coord, ws[coord].value)

# Data sheet inspect
wsd = wb['Data']
print('\n=== Data!A1:Z40 values (None trimmed) ===')
max_col = 26
for r in range(1, 41):
    vals = []
    for c in range(1, max_col+1):
        v = wsd.cell(row=r, column=c).value
        vals.append(v)
    # trim trailing Nones for readability
    while vals and vals[-1] is None:
        vals.pop()
    print(f"{r:02d}", vals)

print('\n=== Data rows 21-38, columns A-Z with coordinates ===')
for r in range(21, 39):
    line = []
    for c in range(1, max_col+1):
        v = wsd.cell(row=r, column=c).value
        if v is not None:
            line.append(f"{get_column_letter(c)}{r}={v}")
    print(f"Row {r}:", ', '.join(line))

PY

